// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

error E(uint256 a, uint256 b);

contract Ir {
    function f(uint256 x) external pure {
        require(x > 0, E({b: 1, a: 2}));
    }

    function even(uint256 n) public pure returns (bool) {
        return n == 0 ? true : odd(n - 1);
    }

    function odd(uint256 n) public pure returns (bool) {
        return n == 0 ? false : even(n - 1);
    }
}
